// Measures whether .gitignore rule placement still affects Worktree.Status()
// cost after go-git#2309 (scoped ignore walk).
//
// Layout mirrors the CLI repo: an ignored e2e/artifacts tree, with the rule
// declared either at the repo root as "e2e/artifacts/" (one level too deep for
// the pre-#2309 flat walk) or in e2e/.gitignore as "/artifacts/".
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"time"

	"github.com/go-git/go-git/v6"
)

const nArtifactDirs = 3000

func main() {
	for _, mode := range []string{"root", "nested"} {
		dir, err := os.MkdirTemp("", "placement-"+mode+"-")
		if err != nil {
			panic(err)
		}
		defer os.RemoveAll(dir)

		build(dir, mode)

		repo, err := git.PlainOpen(dir)
		if err != nil {
			panic(err)
		}
		wt, err := repo.Worktree()
		if err != nil {
			panic(err)
		}

		// Warm the OS cache so we measure the walk, not first-touch I/O.
		if _, err := wt.Status(); err != nil {
			panic(err)
		}

		var best time.Duration
		for i := 0; i < 3; i++ {
			start := time.Now()
			st, err := wt.Status()
			if err != nil {
				panic(err)
			}
			elapsed := time.Since(start)
			if best == 0 || elapsed < best {
				best = elapsed
			}
			if i == 0 {
				fmt.Printf("%-7s rule=%-18s status entries=%d\n", mode, ruleDesc(mode), len(st))
			}
		}
		fmt.Printf("%-7s Status() best of 3: %v\n\n", mode, best.Round(time.Microsecond))

		// Confirm reference git agrees the tree is ignored either way.
		out, err := exec.Command("git", "-C", dir, "status", "--porcelain").Output()
		if err != nil {
			panic(err)
		}
		fmt.Printf("%-7s reference git porcelain lines: %d\n\n", mode, len(splitLines(string(out))))
	}
}

func ruleDesc(mode string) string {
	if mode == "root" {
		return "e2e/artifacts/"
	}
	return "e2e/.gitignore"
}

func splitLines(s string) []string {
	var out []string
	cur := ""
	for _, r := range s {
		if r == '\n' {
			if cur != "" {
				out = append(out, cur)
			}
			cur = ""
			continue
		}
		cur += string(r)
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}

func build(dir, mode string) {
	run := func(args ...string) {
		cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
		if out, err := cmd.CombinedOutput(); err != nil {
			panic(fmt.Sprintf("git %v: %v\n%s", args, err, out))
		}
	}
	run("init", "-q")
	run("config", "user.name", "t")
	run("config", "user.email", "t@t")
	run("config", "commit.gpgsign", "false")

	mustWrite(filepath.Join(dir, "tracked.txt"), "hello\n")

	switch mode {
	case "root":
		mustWrite(filepath.Join(dir, ".gitignore"), "e2e/artifacts/\n")
	case "nested":
		mustWrite(filepath.Join(dir, ".gitignore"), "")
		mustMkdir(filepath.Join(dir, "e2e"))
		mustWrite(filepath.Join(dir, "e2e", ".gitignore"), "/artifacts/\n")
	}

	run("add", "-A")
	run("commit", "-q", "-m", "init", "--no-gpg-sign")

	// Ignored artifact tree: nArtifactDirs directories, each with a file.
	for i := 0; i < nArtifactDirs; i++ {
		d := filepath.Join(dir, "e2e", "artifacts", fmt.Sprintf("run-%04d", i), "logs")
		mustMkdirAll(d)
		mustWrite(filepath.Join(d, "out.txt"), "x\n")
	}
}

func mustWrite(path, content string) {
	mustMkdirAll(filepath.Dir(path))
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		panic(err)
	}
}

func mustMkdir(path string) { mustMkdirAll(path) }

func mustMkdirAll(path string) {
	if err := os.MkdirAll(path, 0o755); err != nil {
		panic(err)
	}
}

